import React from "react";
import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav style={styles.nav}>
      <h2>Doctor Booking</h2>
      <div>
        <Link to="/">Doctors</Link>
        <Link to="/appointments">My Appointments</Link>
        <Link to="/login">Login</Link>
      </div>
    </nav>
  );
}

const styles = {
  nav: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "12px 30px",
    background: "#ffffff",
    boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
  },
  logo: {
    color: "#1976d2",
    margin: 0,
  },
  links: {
    display: "flex",
    gap: "20px",
  },
  link: {
    textDecoration: "none",
  color: "#333",
  fontWeight: "500",
  transition: "0.3s",
  },
  activeLink: {
    textDecoration: "none",
    color: "#1976d2",
    fontWeight: "600",
    borderBottom: "2px solid #1976d2",
  },
  loginBtn: {
    padding: "6px 14px",
    background: "#1976d2",
    color: "#fff",
    borderRadius: "5px",
    textDecoration: "none",
  },
};

export default Navbar;
